import type { DocNetEmail } from 'src/@types/docnet';
import DocNetBaseService from 'src/services/docnet/DocNetBaseService';
import { api } from 'src/pages/APIs';

export default class DocNetEmailService extends DocNetBaseService {
  async fetchEmails(params?: { read?: boolean; skip?: number; limit?: number; search?: string }): Promise<{ items: DocNetEmail[]; total: number; skip: number; limit: number; unread_total: number }> {
    const headers = await this.getHeaders();
    const query = new URLSearchParams({ include_content: 'false' });
    if (params?.read !== undefined) {
      query.set('read', String(params.read));
    }
    if (params?.skip !== undefined) {
      query.set('skip', String(params.skip));
    }
    if (params?.limit !== undefined) {
      query.set('limit', String(params.limit));
    }
    if (params?.search) {
      query.set('search', params.search);
    }
    const response = await super.get(`${api.docnet_emails}?${query.toString()}`, { headers });
    const res = response as any;
    return {
      items: res.items || (response as DocNetEmail[]),
      total: res.total ?? (res.items?.length ?? 0),
      skip: res.skip ?? (params?.skip ?? 0),
      limit: res.limit ?? (params?.limit ?? 50),
      unread_total: res.unread_total ?? 0,
    };
  }

  async fetchEmail(id: string): Promise<DocNetEmail> {
    const headers = await this.getHeaders();
    return (await super.get(`${api.docnet_emails}/${id}?include_content=true`, { headers })) as DocNetEmail;
  }

  async patchEmail(id: string, data: Record<string, any>): Promise<DocNetEmail> {
    const headers = await this.getHeaders();
    return (await super.patch(`${api.docnet_emails}/${id}`, data, {
      headers,
    })) as DocNetEmail;
  }

  async markRead(id: string): Promise<void> {
    const headers = await this.getHeaders();
    await super.patch(`${api.docnet_emails}/${id}/read`, {}, { headers });
  }

  async fetchExtractionResults(emailId: string): Promise<{ email_id: string; documents: any[] }> {
    const headers = await this.getHeaders();
    return (await super.get(`${api.docnet_emails}/${emailId}/extraction-results`, { headers })) as any;
  }
}
